const projectData = $input.first().json;

// Generate project structure based on scope
const phases = {
  'discovery': {
    name: 'Discovery & Analysis',
    duration_weeks: 1,
    deliverables: ['Current state analysis', 'Process mapping', 'Requirements documentation'],
    status: 'not_started'
  },
  'design': {
    name: 'Solution Design',
    duration_weeks: 2,
    deliverables: ['Architecture design', 'Workflow specifications', 'Integration plan'],
    status: 'not_started'
  },
  'development': {
    name: 'Development & Configuration',
    duration_weeks: projectData.complexity === 'high' ? 6 : projectData.complexity === 'medium' ? 4 : 2,
    deliverables: ['Automation workflows', 'Integration setup', 'Testing documentation'],
    status: 'not_started'
  },
  'testing': {
    name: 'Testing & QA',
    duration_weeks: 1,
    deliverables: ['Test results', 'Performance metrics', 'User acceptance testing'],
    status: 'not_started'
  },
  'deployment': {
    name: 'Deployment & Training',
    duration_weeks: 1,
    deliverables: ['Production deployment', 'User training', 'Documentation handover'],
    status: 'not_started'
  }
};

// Calculate timeline
let startDate = new Date();
let currentDate = new Date(startDate);

for (const [phaseId, phase] of Object.entries(phases)) {
  phase.start_date = new Date(currentDate).toISOString();
  currentDate.setDate(currentDate.getDate() + (phase.duration_weeks * 7));
  phase.end_date = new Date(currentDate).toISOString();
}

return {
  project_id: `proj_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  client_name: projectData.client_name,
  project_name: projectData.project_name,
  project_value: projectData.project_value,
  complexity: projectData.complexity,
  phases: phases,
  total_duration_weeks: Object.values(phases).reduce((sum, phase) => sum + phase.duration_weeks, 0),
  project_start: startDate.toISOString(),
  estimated_completion: new Date(currentDate).toISOString(),
  team_size: projectData.complexity === 'high' ? 4 : projectData.complexity === 'medium' ? 3 : 2
};

const projectData = $node['Create Project Structure'].json;

// Auto-assign team based on complexity and availability
const teamAssignments = {
  'project_manager': {
    name: 'Project Manager',
    role: 'pm',
    allocation: 0.3,
    skills: ['project_management', 'client_communication']
  },
  'automation_architect': {
    name: 'Automation Architect',
    role: 'architect',
    allocation: 0.5,
    skills: ['n8n', 'automation_design', 'system_integration']
  }
};

if (projectData.complexity === 'high') {
  teamAssignments['senior_developer'] = {
    name: 'Senior Automation Developer',
    role: 'senior_dev',
    allocation: 0.8,
    skills: ['n8n', 'api_integration', 'custom_development']
  };
  teamAssignments['qa_specialist'] = {
    name: 'QA Specialist',
    role: 'qa',
    allocation: 0.4,
    skills: ['testing', 'quality_assurance', 'automation_testing']
  };
} else if (projectData.complexity === 'medium') {
  teamAssignments['automation_developer'] = {
    name: 'Automation Developer',
    role: 'developer',
    allocation: 0.7,
    skills: ['n8n', 'workflow_development', 'api_integration']
  };
}

return {
  project_id: projectData.project_id,
  team_assignments: teamAssignments,
  team_size: Object.keys(teamAssignments).length
};

const phaseData = $input.first().json;

// Check if all deliverables are completed
const requiredDeliverables = {
  'discovery': ['Current state analysis', 'Process mapping', 'Requirements documentation'],
  'design': ['Architecture design', 'Workflow specifications', 'Integration plan'],
  'development': ['Automation workflows', 'Integration setup', 'Testing documentation'],
  'testing': ['Test results', 'Performance metrics', 'User acceptance testing'],
  'deployment': ['Production deployment', 'User training', 'Documentation handover']
};

const phaseDeliverables = requiredDeliverables[phaseData.phase_name] || [];
const completedDeliverables = phaseData.completed_deliverables || [];
const missingDeliverables = phaseDeliverables.filter(d => !completedDeliverables.includes(d));

return {
  project_id: phaseData.project_id,
  phase_name: phaseData.phase_name,
  phase_complete: missingDeliverables.length === 0,
  completed_deliverables: completedDeliverables,
  missing_deliverables: missingDeliverables,
  completion_percentage: Math.round((completedDeliverables.length / phaseDeliverables.length) * 100),
  can_proceed: missingDeliverables.length === 0
};

